    // ---- CSP delegation helpers (replace former inline expressions; see public/events.js) ----
    function scrollToSection(id) {
      const el = document.getElementById(id);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
    function activateOnEnter(event, fnName) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        const fn = window[fnName];
        if (typeof fn === 'function') fn();
      }
    }
    function openCertificateModalForCurrentTree() { openCertificateModal(state.currentTreeId || 'tree_01'); }
    function openLabCertModalForCurrentTree() { openLabCertModal(state.currentTreeId || 'tree_01'); }
    function openInvestModalKeepLand(treeId) { openInvestModal(treeId, state.includeLandInModal); }
    function toggleCurrencyQuick() { setCurrency(state.currency === 'USD' ? 'SYP' : 'USD'); }
    function toggleLanguageQuick() {
      const index = SUPPORTED_LANGS.indexOf(state.currentLang);
      setLanguage(SUPPORTED_LANGS[(index + 1) % SUPPORTED_LANGS.length]);
    }
    function submitBoutiqueOrder(event) {
      if (event && event.preventDefault) event.preventDefault();
      confirmBoutiqueOrder();
    }
    function clickElement(id) {
      const el = document.getElementById(id);
      if (el) el.click();
    }
    function clearActiveTag(index) {
      const clearer = window._activeTagClearers && window._activeTagClearers[index];
      if (typeof clearer === 'function') clearer();
    }

    // ================= HIGH-PERFORMANCE LUCIDE ENGINE =================
    // Eliminates layout thrashing by batching and coalescing full-DOM icon scans into a single RAF pass
    (function() {
      if (typeof window === 'undefined') return;
      function installLucideAccelerator() {
        if (!window.lucide || !window.lucide.createIcons || window.lucide._accelerated) return;
        const _origCreateIcons = window.lucide.createIcons;
        let _pendingRaf = null;

        const _acceleratedCreateIcons = function(options) {
          if (options && options.root) {
            try { return _origCreateIcons(options); } catch(e) { return _origCreateIcons(); }
          }
          if (_pendingRaf !== null) return;
          if (typeof requestAnimationFrame === 'function') {
            _pendingRaf = requestAnimationFrame(function() {
              _pendingRaf = null;
              try { _origCreateIcons(); } catch(e) {}
            });
          } else {
            _pendingRaf = setTimeout(function() {
              _pendingRaf = null;
              try { _origCreateIcons(); } catch(e) {}
            }, 0);
          }
        };
        _acceleratedCreateIcons._accelerated = true;
        _acceleratedCreateIcons._original = _origCreateIcons;
        window.lucide.createIcons = _acceleratedCreateIcons;
        window.safeCreateIcons = _acceleratedCreateIcons;
      }
      installLucideAccelerator();
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', installLucideAccelerator);
      }
    })();

