    // Capacitor Native Bridge & Hardware Back Button
    
    // Universal Print Lifecycle Handlers (Single-Page Document Isolation)
    window.addEventListener('beforeprint', function() {
      const activeStage = document.body && typeof document.body.getAttribute === 'function' && document.body.getAttribute('data-print-active');
      if (!activeStage) {
        const candidates = [
          'modal-certificate',
          'modal-lab-cert',
          'modal-lab-qr-passport',
          'modal-oil-passport',
          'modal-esg-certificate',
          'modal-investor-statement',
          'modal-farmer-contract',
          'modal-legal-contracts',
          'modal-auth-session'
        ];
        let foundModal = false;
        for (let id of candidates) {
          const el = document.getElementById(id);
          if (el && !el.classList.contains('hidden')) {
            if (typeof populatePrintStage === 'function') populatePrintStage(id);
            foundModal = true;
            break;
          }
        }
        if (!foundModal) {
          const preview = document.getElementById('contract-live-preview-paper');
          const founderPage = document.getElementById('page-founder-control');
          if (preview && founderPage && !founderPage.classList.contains('hidden')) {
            if (typeof populatePrintStage === 'function') populatePrintStage('contract-live-preview-paper');
          }
        }
      }
      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        lucide.createIcons();
      }
    });

    window.addEventListener('afterprint', function() {
      if (document.body && typeof document.body.removeAttribute === 'function') {
        document.body.removeAttribute('data-print-active');
        document.body.removeAttribute('data-print-target');
      }
      const stage = document.getElementById('faseela-print-stage');
      if (stage) stage.innerHTML = '';
    });

    document.addEventListener('DOMContentLoaded', () => {
      // 1. Check Capacitor plugins
      if (window.Capacitor && window.Capacitor.Plugins) {
        const { App, StatusBar, SplashScreen } = window.Capacitor.Plugins;
        if (StatusBar) {
          StatusBar.setStyle({ style: 'DARK' }).catch(() => {});
          StatusBar.setBackgroundColor({ color: '#2c3e2d' }).catch(() => {});
        }
        if (SplashScreen) {
          setTimeout(() => SplashScreen.hide().catch(() => {}), 300);
        }
        if (App) {
          App.addListener('backButton', () => {
            const visibleModals = Array.from(document.querySelectorAll('[id^="modal-"]')).filter(m => !m.classList.contains('hidden'));
            if (visibleModals.length > 0) {
              closeModal(visibleModals[visibleModals.length - 1].id);
              return;
            }
            const current = getCurrentVisiblePage();
            if (current && current !== 'home') {
              navigateTo('home');
            }
          });
        }
      }

      // 2. Web popstate fallback for back button
      window.addEventListener('popstate', () => {
        const visibleModals = Array.from(document.querySelectorAll('[id^="modal-"]')).filter(m => !m.classList.contains('hidden'));
        if (visibleModals.length > 0) {
          closeModal(visibleModals[visibleModals.length - 1].id);
        }
      });

      // Initial network check
      if (!navigator.onLine) {
        updateNetworkStatus();
      }
      loadServerCatalog();
    });


function togglePasswordVisibility(inputId, iconId) {
      const input = document.getElementById(inputId);
      const icon = document.getElementById(iconId);
      if (!input) return;
      if (input.type === 'password') {
        input.type = 'text';
        if (icon) icon.setAttribute('data-lucide', 'eye-off');
      } else {
        input.type = 'password';
        if (icon) icon.setAttribute('data-lucide', 'eye');
      }
      lucide.createIcons();
    }


