    // Audio Chimes & Synthesis
    let audioCtx = null;
    function playAcousticChime(freq, duration) {
      try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') {
          audioCtx.resume().catch(() => {});
        }
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
        osc.start();
        osc.stop(audioCtx.currentTime + duration);
      } catch (e) {}
    }

    function toggleVoiceNote(btnId, waveId, text) {
      const btn = document.getElementById(btnId);
      const wave = document.getElementById(waveId);
      if (!btn) return;
      if (!text && btn.dataset && btn.dataset.voiceText) {
        try {
          text = decodeURIComponent(btn.dataset.voiceText);
        } catch(e) {
          text = btn.dataset.voiceText;
        }
      }
      text = text || '';

      if (btn.classList.contains('playing')) {
        window.speechSynthesis.cancel();
        btn.classList.remove('playing');
        if (wave) wave.classList.remove('playing');
        btn.innerHTML = `<i data-lucide="play" class="w-3.5 h-3.5"></i><span>${t('listen_audio')}</span>`;
      } else {
        document.querySelectorAll('.playing').forEach(el => el.classList.remove('playing'));
        btn.classList.add('playing');
        if (wave) wave.classList.add('playing');
        btn.innerHTML = `<i data-lucide="square" class="w-3.5 h-3.5"></i><span>${state.currentLang !== 'ar' ? 'Stop' : 'إيقاف'}</span>`;

        playAcousticChime(520, 0.2);
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = state.currentLang !== 'ar' ? 'en-US' : 'ar-SY';
        utter.onend = () => {
          btn.classList.remove('playing');
          if (wave) wave.classList.remove('playing');
          btn.innerHTML = `<i data-lucide="play" class="w-3.5 h-3.5"></i><span>${t('listen_audio')}</span>`;
          lucide.createIcons();
        };
        window.speechSynthesis.speak(utter);
      }
      lucide.createIcons();
    }

