    async function submitFarmerVoiceLog() {
      const isEn = state.currentLang !== 'ar';
      if (!state.currentUser || state.currentUser.role !== 'farmer') {
        showAccessDenied(
          t('farmer_btn_record'),
          isEn ? 'Partner Farmer' : 'مزارع شريك معتمد',
          isEn ? 'Only an approved farmer account can submit field reports.' : 'يمكن لحساب المزارع الشريك المعتمد فقط إرسال التقارير الميدانية.'
        );
        return;
      }
      if (!window.FaseelaFirebase) {
        showToast(isEn ? 'Secure field reporting is unavailable.' : 'إرسال التقارير الميدانية الآمن غير متاح حالياً.');
        return;
      }
      if (!rateLimiter.checkLimit('voice_log_' + state.currentUser.id, 5, 60000)) {
        showToast(isEn ? 'Too many reports. Please wait a minute.' : 'تم تجاوز الحد المسموح للتقارير. يرجى الانتظار دقيقة.');
        return;
      }

      const treeId = farmerVoiceState.selectedTreeId;
      const notes = document.getElementById('log-notes')?.value.trim()
        || farmerVoiceState.selectedType
        || '';
      const activity = farmerVoiceState.selectedType || '';
      const eventType = activity.includes('سقاية') || /water|irrigat/i.test(activity) ? 'watering'
        : activity.includes('تقليم') || /prun/i.test(activity) ? 'pruning'
          : activity.includes('تسميد') || /fertiliz/i.test(activity) ? 'fertilizing'
            : activity.includes('مكافحة') || /pest|control/i.test(activity) ? 'pest_control'
              : activity.includes('قطاف') || /harvest/i.test(activity) ? 'harvest'
                : 'other';
      if (!treeId || notes.length > 1200) {
        showToast(isEn ? 'Select a tree and keep the report under 1,200 characters.' : 'اختر شجرة واجعل التقرير أقل من 1200 حرف.');
        return;
      }

      try {
        await window.FaseelaFirebase.submitFarmerUpdate({
          treeId,
          eventType,
          notes,
          mediaPaths: []
        });
        closeModal('modal-add-maintenance');
        playAcousticChime(740, 0.2);
        showToast(isEn
          ? 'Report submitted for review. Audio and photos are not uploaded yet.'
          : 'أُرسل التقرير النصي للمراجعة. لم يُرفع التسجيل الصوتي أو الصور بعد.');
      } catch (error) {
        console.error('Farmer report submission failed:', error);
        showToast(isEn
          ? 'Could not submit the report. Check your farmer assignment and try again.'
          : 'تعذر إرسال التقرير. تحقق من اعتماد حسابك على الشجرة ثم أعد المحاولة.');
      }
    }

    function submitFarmerPayout() {
      if (!state.currentUser || (state.currentUser.role !== 'farmer' && state.currentUser.role !== 'admin')) {
        const reqRole = state.currentLang !== 'ar' ? 'Partner Farmer' : 'مزارع شريك معتمد';
        const msg = state.currentLang !== 'ar' ? 'Subsidies withdrawal is reserved for partner farmers.' : 'طلب صرف المستحقات مخصص فقط للمزارعين الشركاء الموثقين.';
        showAccessDenied(t('farmer_btn_payout'), reqRole, msg);
        return;
      }
      if (!rateLimiter.checkLimit('farmer_payout_' + state.currentUser.id, 2, 60000)) {
        showToast(state.currentLang !== 'ar' ? '⚠️ Please wait a minute before requesting another payout.' : '⚠️ يرجى الانتظار دقيقة قبل إرسال طلب صرف مالي جديد لحماية العمليات.');
        return;
      }

      const methodRadio = document.querySelector('input[name="farmer_payout_method"]:checked');
      const methodVal = methodRadio ? methodRadio.value : 'syriatel_cash';
      const phoneInput = document.getElementById('farmer-payout-phone')?.value || '0944887766';
      const isEn = state.currentLang !== 'ar';

      const withdrawSyp = state.farmerWallet && state.farmerWallet.readySyp > 0 ? state.farmerWallet.readySyp : 630000;
      const withdrawUsd = Math.round(withdrawSyp / 15000);

      // Update state wallet
      if (!state.farmerWallet) {
        state.farmerWallet = { totalSubsidiesSyp: 1890000, readySyp: 630000, paidSyp: 1260000, treesCount: 3, sharesCount: 12 };
      }
      state.farmerWallet.readySyp = Math.max(0, state.farmerWallet.readySyp - withdrawSyp);
      state.farmerWallet.paidSyp = (state.farmerWallet.paidSyp || 0) + withdrawSyp;

      // Create Payout Record
      const newPayoutId = `TX-PAY-00${(state.farmerPayouts ? state.farmerPayouts.length + 1 : 3)}`;
      const channelLabel = methodVal === 'syriatel_cash' ? `سيريتل كاش (${phoneInput})` : `شركة الهرم (فرع الدريكيش)`;
      const channelLabelEn = methodVal === 'syriatel_cash' ? `Syriatel Cash (${phoneInput})` : `Al-Haram Exchange (Dreikiche)`;

      const newPayout = {
        id: newPayoutId,
        date: new Date().toISOString().split('T')[0],
        amount_syp: withdrawSyp,
        amount_usd: withdrawUsd,
        channel: channelLabel,
        channel_en: channelLabelEn,
        status: "completed",
        status_title: "تم التحويل بنجاح",
        status_title_en: "Transferred Successfully",
        receipt_num: methodVal === 'syriatel_cash' ? `SYR-CASH-${Math.floor(Math.random()*90000+10000)}` : `HRM-TRT-${Math.floor(Math.random()*90000+10000)}`,
        work_desc: "بدل رعاية موسمية وأعمال سقاية وتقليم صيفي",
        work_desc_en: "Seasonal Care & Summer Irrigation Subsidy"
      };

      if (!state.farmerPayouts) state.farmerPayouts = [];
      state.farmerPayouts.unshift(newPayout);

      // Add to overall transactions ledger
      if (!state.transactions) state.transactions = [];
      state.transactions.unshift({
        id: newPayout.receipt_num,
        date: newPayout.date,
        type: "سحب أتعاب مزارع",
        type_en: "Farmer Labor Subsidy",
        item: `أتعاب رعاية - العم أبو أحمد (${newPayout.work_desc})`,
        item_en: `Field Care Stipend - Abu Ahmad (${newPayout.work_desc_en})`,
        amount: `${withdrawSyp.toLocaleString()} SYP ($${withdrawUsd})`,
        method: channelLabel,
        status: "مكتمل",
        status_en: "Completed"
      });

      savePlatformState();
      closeModal('modal-farmer-payout');
      playAcousticChime(620, 0.25);
      showToast(isEn ? `✅ Payout of ${withdrawSyp.toLocaleString()} SYP transferred successfully!` : `✅ تم تأكيد صرف وتحويل ${withdrawSyp.toLocaleString()} ل.س بنجاح وإيداع الإشعار بالسجل!`);
      renderFarmerPortal();
      renderDashboard();
    }

    let emergencyRecording = false;
    function toggleEmergencyVoiceRecording() {
      emergencyRecording = !emergencyRecording;
      const btn = document.getElementById('emergency-mic-btn');
      const status = document.getElementById('emergency-voice-status');
      if (emergencyRecording) {
        playAcousticChime(780, 0.2);
        btn.classList.add('animate-pulse', 'ring-8', 'ring-red-300');
        status.innerHTML = `<span class="text-red-700 font-black animate-pulse">${state.currentLang !== 'ar' ? '🔴 Recording emergency alert... speak now' : '🔴 جاري تسجيل نداء الطوارئ... تحدث الآن'}</span>`;
      } else {
        playAcousticChime(500, 0.2);
        btn.classList.remove('animate-pulse', 'ring-8', 'ring-red-300');
        status.innerHTML = `<span class="text-emerald-700 font-bold">${state.currentLang !== 'ar' ? 'Emergency alert captured and ready to broadcast' : 'تم تسجيل النداء وهو جاهز للبث الفوري'}</span>`;
      }
    }

    function submitEmergencyVoiceAlert() {
      if (!state.currentUser || (state.currentUser.role !== 'farmer' && state.currentUser.role !== 'admin')) {
        const reqRole = state.currentLang !== 'ar' ? 'Partner Farmer' : 'مزارع شريك معتمد';
        const msg = state.currentLang !== 'ar' ? 'Emergency field alerts are reserved for verified farmers.' : 'نداءات الطوارئ الحقلية محصورة بالمزارعين والفرق الزراعية الميدانية.';
        showAccessDenied(t('farmer_btn_emergency'), reqRole, msg);
        return;
      }
      if (!rateLimiter.checkLimit('emergency_alert_' + state.currentUser.id, 2, 60000)) {
        showToast(state.currentLang !== 'ar' ? '⚠️ Emergency alert already received. Field team is dispatched.' : '⚠️ تم استلام نداء طوارئ مؤخراً، فرق الدعم تعمل على معالجته.');
        return;
      }

      if (!state.emergencyAlerts) state.emergencyAlerts = [];
      const newAlert = {
        id: `EMG-${Date.now().toString().slice(-4)}`,
        date: new Date().toISOString().replace('T', ' ').slice(0, 16),
        status: 'active',
        desc: 'اشتباه بموجة صقيع مباغتة / رياح شديدة في بساتين الدريكيش',
        desc_en: 'Suspected sudden cold snap / heavy winds in Dreikiche olive groves',
        farmer: state.currentUser.name || 'أبو أحمد الكردي',
        farmer_en: state.currentUser.name_en || 'Abu Ahmad Al-Kurdi'
      };
      state.emergencyAlerts.unshift(newAlert);
      savePlatformState();

      closeModal('modal-emergency-voice');
      playAcousticChime(850, 0.3);
      showToast(state.currentLang !== 'ar' ? '🚨 Emergency audio broadcast dispatched to agronomy response team!' : '🚨 تم بث نداء الطوارئ الصوتي للمهندسين الزراعيين وفريق التدخل الميداني بطرطوس!');
      renderFarmerPortal();
    }

    function resolveEmergencyAlert(alertId) {
      if (state.emergencyAlerts) {
        state.emergencyAlerts = state.emergencyAlerts.filter(a => a.id !== alertId);
        savePlatformState();
        playAcousticChime(700, 0.15);
        showToast(state.currentLang !== 'ar' ? 'Emergency alert marked as resolved by field agronomy team.' : 'تم تأكيد معالجة نداء الطوارئ وإغلاقه من قبل الفريق الزراعي الميداني.');
        renderFarmerPortal();
      }
    }

    // =========================================================
    // MODERN FARMER PORTAL CONTROLLER (5 PILLARS)
    // =========================================================

    function switchFarmerSubTab(tabName) {
      const tabs = ['tasks', 'wallet', 'climate', 'logistics', 'voice_sos'];
      tabs.forEach(t => {
        const btn = document.getElementById(`btn-farmer-tab-${t}`);
        const panel = document.getElementById(`panel-farmer-${t}`);
        if (!btn || !panel) return;

        if (t === tabName) {
          panel.classList.remove('hidden');
          btn.className = "flex-1 min-w-[130px] py-2.5 px-3 rounded-xl transition-all flex items-center justify-center gap-1.5 bg-white dark:bg-stone-900 text-olive-950 dark:text-olive-200 shadow-2xs font-black cursor-pointer";
        } else {
          panel.classList.add('hidden');
          btn.className = "flex-1 min-w-[130px] py-2.5 px-3 rounded-xl transition-all flex items-center justify-center gap-1.5 text-stone-600 hover:text-stone-900 dark:text-stone-300 font-bold cursor-pointer";
        }
      });
      lucide.createIcons();
    }

    function renderServerSubmissions(kind) {
      const isEn = state.currentLang !== 'ar';
      const box = document.getElementById(kind === 'farmer' ? 'farmer-server-submissions' : 'mill-server-submissions');
      const banner = document.getElementById(kind === 'farmer' ? 'farmer-preview-banner' : 'mill-preview-banner');
      if (banner) banner.classList.toggle('hidden', !state.serverMode);
      if (!box) return;
      if (!state.serverMode) { box.classList.add('hidden'); return; }
      box.classList.remove('hidden');
      const items = (kind === 'farmer' ? state.myFarmerUpdates : state.myPressingBatches) || [];
      const label = (status) => window.FaseelaMappers ? window.FaseelaMappers.statusLabel(status, isEn ? 'en' : 'ar') : status;
      const title = kind === 'farmer' ? (isEn ? 'My submitted field reports' : 'تقاريري الميدانية المرسلة') : (isEn ? 'My submitted pressing batches' : 'دفعات العصر المرسلة');
      const rows = items.map(item => {
        const when = Number.isFinite(item.createdAt) ? new Date(item.createdAt).toLocaleDateString(uiLocale()) : '';
        const detail = kind === 'farmer'
          ? `${escapeHtml(item.eventType || '')} • ${escapeHtml((item.notes || '').slice(0, 80))}`
          : `${escapeHtml(item.treeId || '')} • ${escapeHtml(String(item.oilYieldLiters ?? '?'))} L • ${escapeHtml(String(item.acidityPct ?? '?'))}%`;
        return `<li class="flex items-center justify-between gap-3 py-2 border-b border-stone-100 dark:border-stone-800 last:border-0">
          <span class="text-xs text-stone-700 dark:text-stone-200 min-w-0 truncate">${detail}</span>
          <span class="text-[11px] font-bold text-stone-600 dark:text-stone-300 whitespace-nowrap">${escapeHtml(label(item.status))} • ${escapeHtml(when)}</span>
        </li>`;
      }).join('');
      box.innerHTML = `<h3 class="font-black text-sm text-stone-900 dark:text-white mb-2">${title}</h3>${items.length
        ? `<ul>${rows}</ul>`
        : `<p class="text-xs text-stone-600 dark:text-stone-400">${isEn ? 'Nothing submitted yet.' : 'لا توجد إرسالات بعد.'}</p>`}`;
    }

    // ---- Farmer server tools: mobile quick report + public profile (server mode, role farmer) ----
    const farmerQuick = { type: 'watering', files: [], gps: null, gpsPending: false, assignments: null, profile: null, loading: false };

    function farmerToolsAllowed() {
      return !!(state.serverMode && state.currentUser && state.currentUser.role === 'farmer' && window.FaseelaFirebase
        && typeof window.FaseelaFirebase.myAssignments === 'function');
    }

    async function renderFarmerServerTools() {
      const wrap = document.getElementById('farmer-server-tools');
      if (!wrap) return;
      if (!farmerToolsAllowed()) { wrap.classList.add('hidden'); return; }
      wrap.classList.remove('hidden');
      fqrSelectType(farmerQuick.type);
      if (farmerQuick.uid !== state.currentUser.id) { farmerQuick.uid = state.currentUser.id; farmerQuick.assignments = null; farmerQuick.profile = null; }
      if (farmerQuick.assignments === null && !farmerQuick.loading) {
        farmerQuick.loading = true;
        try {
          const [assignments, profile] = await Promise.all([
            window.FaseelaFirebase.myAssignments(),
            window.FaseelaFirebase.myFarmerProfile()
          ]);
          farmerQuick.assignments = assignments || { trees: [], mills: [] };
          farmerQuick.profile = profile;
        } catch (error) {
          console.error('Farmer tools load failed:', error);
          farmerQuick.assignments = { trees: [], mills: [] };
        } finally {
          farmerQuick.loading = false;
        }
      }
      renderFqrTrees();
      renderFarmerProfileForm();
      if (window.lucide) window.lucide.createIcons();
    }

    function renderFqrTrees() {
      const sel = document.getElementById('fqr-tree');
      const none = document.getElementById('fqr-no-trees');
      if (!sel) return;
      const isEn = state.currentLang !== 'ar';
      const trees = (farmerQuick.assignments && farmerQuick.assignments.trees) || [];
      const current = sel.value;
      sel.innerHTML = trees.map(tr => {
        const name = isEn ? (tr.nameEn || tr.name) : (tr.name || tr.nameEn);
        const region = isEn ? (tr.regionEn || tr.region) : (tr.region || tr.regionEn);
        return `<option value="${escapeHtml(tr.treeId)}">${escapeHtml(name || tr.treeId)}${region ? ' • ' + escapeHtml(region) : ''}</option>`;
      }).join('');
      if (current && trees.some(tr => tr.treeId === current)) sel.value = current;
      sel.disabled = trees.length === 0;
      if (none) none.classList.toggle('hidden', trees.length > 0 || farmerQuick.assignments === null);
      const submit = document.getElementById('fqr-submit');
      if (submit) submit.disabled = trees.length === 0;
    }

    function fqrSelectType(type) {
      const allowed = ['watering', 'pruning', 'fertilizing', 'pest_control', 'harvest', 'other'];
      farmerQuick.type = allowed.includes(type) ? type : 'watering';
      document.querySelectorAll('#fqr-types [data-fqr-type]').forEach(btn => {
        const active = btn.getAttribute('data-fqr-type') === farmerQuick.type;
        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
        btn.classList.toggle('bg-olive-800', active);
        btn.classList.toggle('text-white', active);
        btn.classList.toggle('border-olive-800', active);
      });
    }

    const FIELD_PHOTO_TYPES = ['image/jpeg', 'image/png', 'image/webp'];
    const FIELD_PHOTO_MAX = 10 * 1024 * 1024;

    function fqrShowError(msg) {
      const el = document.getElementById('fqr-error');
      if (!el) return;
      el.textContent = msg || '';
      el.classList.toggle('hidden', !msg);
    }

    function fqrPhotosChanged() {
      const input = document.getElementById('fqr-photos');
      const files = Array.from((input && input.files) || []);
      const bad = files.length > 5 || files.some(f => !FIELD_PHOTO_TYPES.includes(f.type) || f.size > FIELD_PHOTO_MAX);
      if (bad) {
        farmerQuick.files = [];
        if (input) input.value = '';
        fqrShowError(t('fqr_err_photos'));
      } else {
        farmerQuick.files = files;
        fqrShowError('');
      }
      renderFqrPreview();
    }

    function renderFqrPreview() {
      const box = document.getElementById('fqr-photo-preview');
      if (!box) return;
      box.querySelectorAll('img[data-blob]').forEach(img => URL.revokeObjectURL(img.getAttribute('data-blob')));
      box.innerHTML = farmerQuick.files.map((f, i) => {
        const url = URL.createObjectURL(f);
        return `<figure class="relative m-0"><img src="${url}" data-blob="${url}" alt="" width="72" height="72" class="w-18 h-18 rounded-xl object-cover border border-stone-200 dark:border-stone-700">
          <button type="button" data-click="fqrRemovePhoto(${i})" class="absolute -top-1.5 -end-1.5 w-6 h-6 rounded-full bg-stone-900/80 text-white text-xs font-bold flex items-center justify-center cursor-pointer" aria-label="${escapeHtml(t('fqr_remove_photo'))} ${i + 1}">×</button></figure>`;
      }).join('');
    }

    function fqrRemovePhoto(index) {
      farmerQuick.files = farmerQuick.files.filter((_, i) => i !== index);
      const input = document.getElementById('fqr-photos');
      if (input && farmerQuick.files.length === 0) input.value = '';
      renderFqrPreview();
    }

    function fqrGpsToggled(checked) {
      const status = document.getElementById('fqr-gps-status');
      farmerQuick.gps = null;
      if (!checked) { if (status) status.textContent = ''; return; }
      if (!navigator.geolocation) { fqrShowError(t('fqr_err_gps')); return; }
      farmerQuick.gpsPending = true;
      if (status) status.textContent = '…';
      navigator.geolocation.getCurrentPosition((pos) => {
        farmerQuick.gpsPending = false;
        farmerQuick.gps = { lat: Number(pos.coords.latitude.toFixed(6)), lng: Number(pos.coords.longitude.toFixed(6)) };
        if (status) status.textContent = `${farmerQuick.gps.lat}, ${farmerQuick.gps.lng}`;
        fqrShowError('');
      }, () => {
        farmerQuick.gpsPending = false;
        const box = document.getElementById('fqr-gps');
        if (box) box.checked = false;
        if (status) status.textContent = '';
        fqrShowError(t('fqr_err_gps'));
      }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 });
    }

    async function submitQuickReport() {
      if (!farmerToolsAllowed()) return;
      const sel = document.getElementById('fqr-tree');
      const treeId = sel ? sel.value : '';
      const trees = (farmerQuick.assignments && farmerQuick.assignments.trees) || [];
      if (!treeId || !trees.some(tr => tr.treeId === treeId)) { fqrShowError(t('fqr_err_tree')); return; }
      if (!rateLimiter.checkLimit('quick_report_' + state.currentUser.id, 5, 60000)) {
        showToast(state.currentLang !== 'ar' ? 'Too many reports. Please wait a minute.' : 'تم تجاوز الحد المسموح للتقارير. يرجى الانتظار دقيقة.');
        return;
      }
      const notes = (document.getElementById('fqr-notes')?.value || '').trim().slice(0, 1200);
      const btn = document.getElementById('fqr-submit');
      const label = btn ? btn.querySelector('span') : null;
      if (btn) btn.disabled = true;
      if (label) label.textContent = t('fqr_sending');
      fqrShowError('');
      try {
        const mediaPaths = [];
        for (const file of farmerQuick.files) {
          mediaPaths.push(await window.FaseelaFirebase.uploadFieldMedia(treeId, file));
        }
        const payload = { treeId, eventType: farmerQuick.type, notes, mediaPaths };
        if (farmerQuick.gps) { payload.gpsLat = farmerQuick.gps.lat; payload.gpsLng = farmerQuick.gps.lng; }
        await window.FaseelaFirebase.submitFarmerUpdate(payload);
        farmerQuick.files = [];
        farmerQuick.gps = null;
        const photos = document.getElementById('fqr-photos');
        if (photos) photos.value = '';
        const notesEl = document.getElementById('fqr-notes');
        if (notesEl) notesEl.value = '';
        const gpsBox = document.getElementById('fqr-gps');
        if (gpsBox) gpsBox.checked = false;
        const gpsStatus = document.getElementById('fqr-gps-status');
        if (gpsStatus) gpsStatus.textContent = '';
        renderFqrPreview();
        playAcousticChime(740, 0.2);
        showToast(t('fqr_ok'));
      } catch (error) {
        console.error('Quick report failed:', error);
        fqrShowError(error && error.message && /^[A-Za-z]/.test(error.message) && state.currentLang !== 'ar' ? error.message : t('fqr_fail'));
      } finally {
        if (btn) btn.disabled = false;
        if (label) label.textContent = t('fqr_submit');
      }
    }

    function fpShowError(msg) {
      const el = document.getElementById('fp-error');
      if (!el) return;
      el.textContent = msg || '';
      el.classList.toggle('hidden', !msg);
    }

    function renderFarmerProfileForm() {
      const p = farmerQuick.profile;
      const isEn = state.currentLang !== 'ar';
      const set = (id, v) => { const el = document.getElementById(id); if (el && document.activeElement !== el) el.value = v == null ? '' : String(v); };
      set('fp-name', p?.displayName);
      set('fp-village', p?.village);
      set('fp-region', p?.region);
      set('fp-years', p?.yearsFarming);
      set('fp-bio', p?.bio);
      set('fp-bio-en', p?.bioEn);
      const consent = document.getElementById('fp-consent');
      if (consent) consent.checked = !!(p && p.consentPublic);
      const status = document.getElementById('fp-status');
      if (status) {
        const trees = (farmerQuick.assignments && farmerQuick.assignments.trees) || [];
        const links = trees.slice(0, 3).map(tr => `<a href="tree.html?tree=${encodeURIComponent(tr.treeId)}&lang=${isEn ? 'en' : 'ar'}" target="_blank" rel="noopener" class="underline text-olive-800 dark:text-olive-300">${escapeHtml(t('fp_view_tree'))}: ${escapeHtml(isEn ? (tr.nameEn || tr.name || tr.treeId) : (tr.name || tr.nameEn || tr.treeId))}</a>`).join('');
        const when = p && p.consentAt ? new Date(p.consentAt).toLocaleDateString(uiLocale()) : '';
        status.innerHTML = (p && p.consentPublic
          ? `<span class="px-2 py-0.5 rounded-md bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300">${escapeHtml(t('fp_status_public'))} ${escapeHtml(when)}</span>`
          : `<span class="px-2 py-0.5 rounded-md bg-stone-100 dark:bg-stone-800">${escapeHtml(t('fp_status_private'))}</span>`) + links;
      }
      const ph = document.getElementById('fp-photo-ph');
      if (ph) ph.textContent = (p && p.displayName ? String(p.displayName).trim().charAt(0) : (isEn ? 'F' : 'م')) || 'م';
    }

    function fpPhotoChanged() {
      const input = document.getElementById('fp-photo');
      const file = input && input.files && input.files[0];
      const img = document.getElementById('fp-photo-preview');
      const ph = document.getElementById('fp-photo-ph');
      if (!file) return;
      if (!FIELD_PHOTO_TYPES.includes(file.type) || file.size > FIELD_PHOTO_MAX) {
        input.value = '';
        fpShowError(t('fp_err_photo'));
        return;
      }
      fpShowError('');
      if (img) {
        if (img.dataset.blob) URL.revokeObjectURL(img.dataset.blob);
        const url = URL.createObjectURL(file);
        img.src = url; img.dataset.blob = url; img.classList.remove('hidden');
        if (ph) ph.classList.add('hidden');
      }
    }

    async function saveFarmerProfile() {
      if (!farmerToolsAllowed()) return;
      const val = (id) => (document.getElementById(id)?.value || '').trim();
      const consent = !!document.getElementById('fp-consent')?.checked;
      const name = val('fp-name');
      if (consent && name.length < 2) { fpShowError(t('fp_err_name')); return; }
      if (!rateLimiter.checkLimit('farmer_profile_' + state.currentUser.id, 5, 60000)) {
        showToast(state.currentLang !== 'ar' ? 'Please wait a minute before saving again.' : 'يرجى الانتظار دقيقة قبل الحفظ مجدداً.');
        return;
      }
      const btn = document.getElementById('fp-save');
      const label = btn ? btn.querySelector('span') : null;
      if (btn) btn.disabled = true;
      if (label) label.textContent = t('fp_saving');
      fpShowError('');
      try {
        const payload = { displayName: name, village: val('fp-village'), region: val('fp-region'), bio: val('fp-bio'), bioEn: val('fp-bio-en'), consentPublic: consent };
        const years = val('fp-years');
        if (years !== '' && Number.isFinite(Number(years))) payload.yearsFarming = Math.max(0, Math.min(90, Math.round(Number(years))));
        const photoInput = document.getElementById('fp-photo');
        const photo = photoInput && photoInput.files && photoInput.files[0];
        if (photo) payload.photoPath = await window.FaseelaFirebase.uploadFarmerProfilePhoto(photo);
        else if (farmerQuick.profile && farmerQuick.profile.photoPath) payload.photoPath = farmerQuick.profile.photoPath;
        const { data } = await window.FaseelaFirebase.updateFarmerProfile(payload);
        // The RPC echoes the editable fields; consent_at/consent_version come from a fresh owner read.
        try { farmerQuick.profile = await window.FaseelaFirebase.myFarmerProfile(); } catch (readError) { console.warn('Profile re-read failed:', readError); farmerQuick.profile = null; }
        if (!farmerQuick.profile && data && typeof data === 'object') farmerQuick.profile = data;
        if (photoInput) photoInput.value = '';
        renderFarmerProfileForm();
        playAcousticChime(640, 0.15);
        showToast(t('fp_saved'));
      } catch (error) {
        console.error('Farmer profile save failed:', error);
        fpShowError(error && error.message && /^[A-Za-z]/.test(error.message) && state.currentLang !== 'ar' ? error.message : t('fp_fail'));
      } finally {
        if (btn) btn.disabled = false;
        if (label) label.textContent = t('fp_save');
      }
    }

    function renderFarmerPortal() {
      renderServerSubmissions('farmer');
      renderFarmerServerTools();
      const isEn = state.currentLang !== 'ar';
      if (typeof switchWeatherProvince === 'function') {
        switchWeatherProvince(state.selectedWeatherProvince || 'tartus');
      }

      // 0. Update KPI summary cards
      const fTreesEl = document.getElementById('farmer-stat-trees');
      if (fTreesEl) fTreesEl.innerText = `${state.farmerWallet?.treesCount || 3} ${isEn ? t('dash_trees_unit_plural') : t('dash_trees_unit_plural')}`;

      const compTasks = (state.farmerTasks || []).filter(t => t.status === 'completed').length;
      const remTasks = (state.farmerTasks || []).length - compTasks;
      const fTasksEl = document.getElementById('farmer-stat-tasks');
      if (fTasksEl) fTasksEl.innerText = `${compTasks} ${t('farmer_kpi_tasks_done')} • ${remTasks} ${t('farmer_kpi_tasks_rem')}`;

      const fWagesEl = document.getElementById('farmer-stat-wages');
      if (fWagesEl) fWagesEl.innerText = `${(state.farmerWallet?.totalSubsidiesSyp || 1890000).toLocaleString()} ${isEn ? 'SYP' : 'ل.س'}`;

      const fMillEl = document.getElementById('farmer-stat-mill');
      if (fMillEl) fMillEl.innerText = isEn ? 'Sept 15 • 8:00 AM' : '15 أيلول • 8:00 ص';

      const wTotalSub = document.getElementById('farmer-wallet-total-sub');
      if (wTotalSub) wTotalSub.innerText = `${isEn ? 'SYP' : 'ل.س'} ($126)`;

      const wReadySub = document.getElementById('farmer-wallet-ready-sub');
      if (wReadySub) wReadySub.innerText = `${isEn ? 'SYP' : 'ل.س'} ($42)`;

      const wShares = document.getElementById('farmer-wallet-shares-count');
      if (wShares) wShares.innerText = isEn ? 'Ancient Trees (12 Shares)' : 'أشجار معمرة (12 حصة)';

      // 1. Render Tasks in Panel 1
      const tasksContainer = document.getElementById('farmer-tasks-list');
      if (tasksContainer && state.farmerTasks) {
        tasksContainer.innerHTML = state.farmerTasks.map(task => {
          const isDone = task.status === 'completed';
          const title = isEn ? task.title_en : task.title;
          const category = isEn ? task.category_en : task.category;
          const treeName = isEn ? task.tree_name_en : task.tree_name;

          return `
            <div class="bg-white dark:bg-stone-850 p-4 rounded-2xl border ${isDone ? 'border-emerald-200 dark:border-emerald-800/60 bg-emerald-50/20 dark:bg-emerald-950/10' : 'border-stone-200 dark:border-stone-700'} shadow-2xs flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-start transition-all">
              <div class="flex items-start gap-3">
                <div class="w-8 h-8 rounded-xl ${isDone ? 'bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300' : 'bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300'} flex items-center justify-center flex-shrink-0 mt-0.5">
                  <i data-lucide="${isDone ? 'check-circle' : 'clock'}" class="w-4 h-4"></i>
                </div>
                <div>
                  <div class="flex items-center gap-2 flex-wrap">
                    <span class="font-black text-stone-900 dark:text-white text-xs sm:text-sm">${title}</span>
                    <span class="text-[10px] bg-stone-100 dark:bg-stone-700 text-stone-600 dark:text-stone-300 px-2 py-0.2 rounded font-bold">${category}</span>
                  </div>
                  <div class="flex items-center gap-2 text-[11px] text-stone-500 dark:text-stone-400 mt-1">
                    <span>${treeName}</span>
                    <span>•</span>
                    <span class="font-bold text-olive-800 dark:text-olive-300 font-mono">${task.wage_syp.toLocaleString()} ${isEn ? 'SYP Wage' : 'ل.س بدل الإنجاز'}</span>
                  </div>
                </div>
              </div>

              <div>
                ${isDone ? `
                  <span class="inline-flex items-center gap-1 text-[11px] font-bold text-emerald-800 dark:text-emerald-300 bg-emerald-100 dark:bg-emerald-950 px-3 py-1.5 rounded-xl border border-emerald-200 dark:border-emerald-800">
                    <i data-lucide="check" class="w-3.5 h-3.5"></i>
                    <span>${isEn ? 'Completed & Credited' : 'تم الإنجاز وإيداع البدل'}</span>
                  </span>
                ` : `
                  <button type="button" data-click="completeFarmerTask('${task.id}')" class="w-full sm:w-auto bg-emerald-700 hover:bg-emerald-800 text-white px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-xs flex items-center justify-center gap-1.5 cursor-pointer">
                    <i data-lucide="check-square" class="w-3.5 h-3.5"></i>
                    <span>${isEn ? 'Complete & Claim Wage' : 'تم الإنجاز (إيداع البدل)'}</span>
                  </button>
                `}
              </div>
            </div>
          `;
        }).join('');
      }

      // 2. Render Trees in Panel 1 bottom
      const treesContainer = document.getElementById('farmer-trees-list');
      if (treesContainer) {
        treesContainer.innerHTML = state.trees.map(tree => {
          const latestVoiceLog = tree.maintenance_logs.find(l => l.has_voice_note);
          const displayName = isEn ? (tree.tree_name_en || tree.tree_name) : tree.tree_name;
          const displayRegion = isEn ? (tree.region_detail_en || tree.region_detail) : tree.region_detail;
          const displayHealth = isEn ? (tree.health_status_en || tree.health_status) : tree.health_status;

          return `
            <div class="border border-stone-200 dark:border-stone-800 rounded-3xl p-5 sm:p-6 bg-gradient-to-br from-stone-50 via-white to-stone-50/80 dark:from-stone-850 dark:via-stone-900 dark:to-stone-850 shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-5 text-start">
              <div class="flex items-start sm:items-center gap-4">
                <img alt="${escapeHtml((isEn ? (tree.tree_name_en || tree.tree_name) : tree.tree_name) || '')}" loading="lazy" src="${tree.images[0]}" class="w-20 h-20 sm:w-24 sm:h-24 rounded-2xl object-cover border border-stone-200 dark:border-stone-700 flex-shrink-0">
                <div class="space-y-1.5">
                  <div class="flex flex-wrap items-center gap-2">
                    <h4 class="text-base sm:text-lg font-black text-stone-900 dark:text-white">${displayName}</h4>
                    <span class="bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300 text-[10px] font-black px-2.5 py-0.5 rounded-full">${displayHealth}</span>
                    <span class="bg-stone-100 dark:bg-stone-700 text-stone-600 dark:text-stone-300 text-[10px] font-bold px-2 py-0.5 rounded">${tree.age_years} ${t('year_unit')}</span>
                  </div>
                  <p class="text-xs text-stone-500 dark:text-stone-400">${displayRegion} • ${tree.maintenance_logs.length} ${isEn ? 'Field Reports' : 'تقارير موثقة'}</p>

                  ${latestVoiceLog ? `
                    <div class="inline-flex items-center gap-2 bg-emerald-50 dark:bg-emerald-950/60 text-emerald-950 dark:text-emerald-200 border border-emerald-200 dark:border-emerald-800 px-3 py-1.5 rounded-xl text-xs font-bold mt-1">
                      <button type="button" id="flist-btn-${tree.id}" data-voice-text="${encodeURIComponent(latestVoiceLog.notes || '')}" data-click="toggleVoiceNote('flist-btn-${tree.id}', 'flist-wave-${tree.id}')" class="bg-emerald-700 hover:bg-emerald-800 text-white px-2 py-1 rounded-lg text-[10px] flex items-center gap-1 cursor-pointer">
                        <i data-lucide="play" class="w-3 h-3"></i>
                        <span>${t('listen_audio')}</span>
                      </button>
                      <span class="text-[11px]">${isEn ? 'Latest Audio: ' + (latestVoiceLog.type_en || latestVoiceLog.type) : 'آخر تسجيل: ' + latestVoiceLog.type}</span>
                      <div id="flist-wave-${tree.id}" class="flex items-center gap-0.5 ms-1">
                        <span class="audio-wave-bar"></span>
                        <span class="audio-wave-bar"></span>
                        <span class="audio-wave-bar"></span>
                        <span class="text-[10px] font-mono text-stone-500 dark:text-stone-400 ms-1">${latestVoiceLog.voice_duration || '0:18'}</span>
                      </div>
                    </div>
                  ` : ''}
                </div>
              </div>

              <button data-click="openVoiceRecorderModal('${tree.id}')" class="bg-emerald-700 hover:bg-emerald-800 text-white px-5 py-3 rounded-2xl font-black text-xs flex items-center justify-center gap-2 shadow-sm cursor-pointer">
                <i data-lucide="mic" class="w-4 h-4 text-amber-300"></i>
                <span>${t('farmer_btn_record')}</span>
              </button>
            </div>
          `;
        }).join('');
      }

      // 3. Render Requisitions in Panel 4
      const reqContainer = document.getElementById('farmer-req-list');
      if (reqContainer && state.farmerRequisitions) {
        reqContainer.innerHTML = state.farmerRequisitions.map(req => {
          const item = isEn ? req.item_en : req.item;
          const status = isEn ? req.status_en : req.status_ar;
          const isDelivered = req.status === 'delivered';

          return `
            <div class="p-3 bg-stone-50 dark:bg-stone-800 rounded-xl border border-stone-200 dark:border-stone-700 flex items-center justify-between">
              <div>
                <span class="font-bold text-stone-900 dark:text-white block">${item}</span>
                <span class="text-[10px] text-stone-500 dark:text-stone-400">${req.date}</span>
              </div>
              <span class="text-[10px] font-bold px-2 py-0.5 rounded-full ${isDelivered ? 'bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300' : 'bg-amber-100 dark:bg-amber-950 text-amber-800 dark:text-amber-300'}">
                ${status}
              </span>
            </div>
          `;
        }).join('');
      }

      // 4. Render Voice Logs in Panel 5
      const voiceFeedContainer = document.getElementById('farmer-recent-voice-logs');
      if (voiceFeedContainer) {
        const allVoiceLogs = [];
        state.trees.forEach(t => {
          t.maintenance_logs.filter(l => l.has_voice_note).forEach(l => {
            allVoiceLogs.push({ ...l, treeName: isEn ? (t.tree_name_en || t.tree_name) : t.tree_name });
          });
        });

        voiceFeedContainer.innerHTML = allVoiceLogs.slice(0, 4).map((vlog, idx) => `
          <div class="bg-stone-50 dark:bg-stone-800 border border-stone-200 dark:border-stone-700 p-3 rounded-2xl flex items-center justify-between text-xs text-start text-stone-800 dark:text-stone-200">
            <div class="flex items-center gap-3">
              <button type="button" id="vfeed-btn-${idx}" data-voice-text="${encodeURIComponent(vlog.notes || '')}" data-click="toggleVoiceNote('vfeed-btn-${idx}', 'vfeed-wave-${idx}')" class="w-8 h-8 rounded-xl bg-emerald-700 hover:bg-emerald-800 text-white flex items-center justify-center flex-shrink-0 cursor-pointer">
                <i data-lucide="play" class="w-3.5 h-3.5"></i>
              </button>
              <div>
                <h5 class="font-bold text-stone-900 dark:text-white">${escapeHtml(vlog.treeName)} • ${escapeHtml(isEn ? (vlog.type_en || vlog.type) : vlog.type)}</h5>
                <p class="text-[11px] text-stone-500 dark:text-stone-400">${escapeHtml(vlog.notes)}</p>
              </div>
            </div>
            <span class="text-[10px] font-mono text-stone-500 dark:text-stone-400">${vlog.voice_duration}</span>
          </div>
        `).join('');
      }

      lucide.createIcons();
    }

    function completeFarmerTask(taskId) {
      const task = state.farmerTasks?.find(t => t.id === taskId);
      if (!task) return;
      const isEn = state.currentLang !== 'ar';

      if (!state.currentUser || (state.currentUser.role !== 'farmer' && state.currentUser.role !== 'admin')) {
        const reqRole = isEn ? 'Certified Field Farmer' : 'مزارع ميداني معتمد';
        const msg = isEn ? 'Completing tasks and claiming wages is restricted to certified farmers.' : 'تأكيد إنجاز المهام وقيد الأتعاب مقتصر على المزارعين المعتمدين.';
        showAccessDenied(t('farmer_tasks_title'), reqRole, msg);
        return;
      }

      task.status = 'completed';
      if (!state.farmerWallet) {
        state.farmerWallet = { totalSubsidiesSyp: 1890000, readySyp: 630000, paidSyp: 1260000, treesCount: 3, sharesCount: 12 };
      }
      state.farmerWallet.readySyp = (state.farmerWallet.readySyp || 0) + task.wage_syp;
      state.farmerWallet.totalSubsidiesSyp = (state.farmerWallet.totalSubsidiesSyp || 0) + task.wage_syp;
      playAcousticChime(700, 0.2);
      showToast(isEn ? `✅ Task completed! ${task.wage_syp.toLocaleString()} SYP credited to your labor wallet.` : `✅ تم إنجاز المهمة بنجاح! تم قيد ${task.wage_syp.toLocaleString()} ل.س في محفظة أتعابك.`);
      renderFarmerPortal();
    }

    function bookFarmerMillDelivery() {
      const isEn = state.currentLang !== 'ar';
      if (!state.currentUser || (state.currentUser.role !== 'farmer' && state.currentUser.role !== 'admin')) {
        const reqRole = isEn ? 'Certified Field Farmer' : 'مزارع ميداني معتمد';
        const msg = isEn ? 'Mill slot booking is restricted to certified farmers.' : 'حجز دور المعصرة مقتصر على المزارعين المعتمدين.';
        showAccessDenied(t('farmer_mill_booking_title'), reqRole, msg);
        return;
      }
      showToast(isEn ? "📅 Cold-press milling slot confirmed for Sept 15 with Eng. Samir at Dreikish Mill." : "📅 تم تأكيد حجز دور العصر البارد ليوم 15 أيلول بنجاح مع معصرة الدريكيش الحديثة.");
      playAcousticChime(600, 0.15);
    }

    function requestFarmerInput(itemKey) {
      const isEn = state.currentLang !== 'ar';
      showToast(isEn ? "📦 Equipment requisition sent to cooperative: 50 ventilated crates scheduled for delivery." : "📦 تم إرسال طلب المستلزمات بنجاح: سيتم تسليم 50 صندوقاً مهواة لمزرعتك غداً.");
      playAcousticChime(650, 0.15);
    }

    // Dynamic Lab Quality Certificate Modal Loader
    function openLabCertificateModal(batchSerial = null) {
      const isEn = state.currentLang !== 'ar';
      const batch = (batchSerial ? state.millBatches.find(b => b.serial === batchSerial) : null) || state.millBatches[0] || {
        serial: "SYR-MILL-2025-0981",
        tree_name: "الشجرة المعمرة - حارسة الجبل",
        tree_name_en: "The Century Olive - Mountain Guardian",
        farm_name: "مزرعة كروم الكردي (طرطوس)",
        farm_name_en: "Al-Kurdi Groves (Tartus)",
        olives_kg: 68.5,
        oil_liters: 14.8,
        acidity: "0.32%",
        temp: "23.8° C",
        grade: "بكر ممتاز فائق (Extra Virgin)",
        grade_en: "Super Extra Virgin Olive Oil"
      };

      const displayName = isEn ? (batch.tree_name_en || batch.tree_name) : batch.tree_name;
      const displayFarm = isEn ? (batch.farm_name_en || batch.farm_name) : batch.farm_name;
      const displayGrade = isEn ? (batch.grade_en || batch.grade) : batch.grade;
      const yieldRate = ((batch.oil_liters * 0.916) / (batch.olives_kg || 1) * 100).toFixed(1);

      const serialEl = document.getElementById('lab-cert-batch-serial');
      if (serialEl) serialEl.innerText = `${isEn ? 'Accreditation No:' : 'رقم الاعتماد:'} ${batch.serial}`;

      const treeEl = document.getElementById('lab-cert-tree-name');
      if (treeEl) treeEl.innerText = displayName;

      const farmEl = document.getElementById('lab-cert-farm-name');
      if (farmEl) farmEl.innerText = displayFarm;

      const weightOilEl = document.getElementById('lab-cert-weight-oil');
      if (weightOilEl) weightOilEl.innerText = isEn ? `${batch.olives_kg} kg Fruit ➔ ${batch.oil_liters} L EVOO` : `${batch.olives_kg} كغ ثمار ➔ ${batch.oil_liters} لتر زيت`;

      const yieldEl = document.getElementById('lab-cert-yield-rate');
      if (yieldEl) yieldEl.innerText = `${isEn ? 'Extraction Yield:' : 'نسبة السيولة:'} ${yieldRate}%`;

      const acidityEl = document.getElementById('lab-cert-acidity');
      if (acidityEl) acidityEl.innerText = `${batch.acidity} ${isEn ? '(International limit < 0.8%)' : '(المعيار الدولي أقل من 0.8%)'}`;

      const tempEl = document.getElementById('lab-cert-temp');
      if (tempEl) tempEl.innerText = `${batch.temp} ${isEn ? '(True Cold Pressing)' : '(عصر بارد حقيقي)'}`;

      const badgeEl = document.getElementById('lab-cert-grade-badge');
      if (badgeEl) badgeEl.innerText = displayGrade;

      openLabCertModal(state.currentTreeId || 'tree_01');
      lucide.createIcons();
    }

        // Olive Mill Portal
