    function askFaseelaQuick(text) {
      document.getElementById('faseela-chat-input').value = text;
      handleFaseelaChatSubmit(new Event('submit'));
    }

    // ================= FASEELA VOICE INPUT SYSTEM (Web Speech API) =================
    let _faseelaVoiceRecognition = null;
    let _faseelaVoiceActive = false;

    function isSpeechRecognitionSupported() {
      return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
    }

    function toggleFaseelaVoiceInput() {
      if (_faseelaVoiceActive) {
        stopFaseelaVoiceInput();
      } else {
        startFaseelaVoiceInput();
      }
    }

    function startFaseelaVoiceInput() {
      const isEn = state.currentLang !== 'ar';

      // Check browser support
      if (!isSpeechRecognitionSupported()) {
        showToast(t('voice_error_no_support'));
        return;
      }

      // Prevent double-start
      if (_faseelaVoiceActive) return;

      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      _faseelaVoiceRecognition = new SpeechRecognition();

      // Configure recognition
      _faseelaVoiceRecognition.lang = isEn ? 'en-US' : 'ar-SA';
      _faseelaVoiceRecognition.interimResults = true;
      _faseelaVoiceRecognition.continuous = false;
      _faseelaVoiceRecognition.maxAlternatives = 1;

      const input = document.getElementById('faseela-chat-input');
      const voiceBtn = document.getElementById('faseela-voice-btn');
      const statusBar = document.getElementById('faseela-voice-status');
      const statusText = document.getElementById('faseela-voice-status-text');

      // Activate UI state
      _faseelaVoiceActive = true;
      if (voiceBtn) {
        voiceBtn.classList.add('voice-rec-active');
        // Add pulsing ring
        const ring = document.createElement('span');
        ring.className = 'voice-rec-ring';
        ring.id = 'voice-rec-ring-el';
        voiceBtn.appendChild(ring);
        // Switch icon to mic-off
        const icon = voiceBtn.querySelector('[data-lucide]');
        if (icon) {
          icon.setAttribute('data-lucide', 'mic-off');
          if (window.lucide) lucide.createIcons();
        }
      }
      if (statusBar) {
        statusBar.classList.remove('hidden');
        if (statusText) statusText.textContent = t('voice_listening');
      }
      triggerHaptic('medium');

      // Handle interim & final results
      _faseelaVoiceRecognition.onresult = function(event) {
        let finalTranscript = '';
        let interimTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; i++) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalTranscript += transcript;
          } else {
            interimTranscript += transcript;
          }
        }

        // Show interim results in input field (live feedback)
        if (input) {
          if (finalTranscript) {
            input.value = finalTranscript;
          } else if (interimTranscript) {
            input.value = interimTranscript;
            if (statusText) statusText.textContent = t('voice_processing');
          }
        }
      };

      // When recognition ends naturally
      _faseelaVoiceRecognition.onend = function() {
        _faseelaVoiceActive = false;
        resetVoiceUI();

        // Auto-submit if we got text
        if (input && input.value.trim().length > 0) {
          _lastQuestionWasVoice = true;
          triggerHaptic('light');
          handleFaseelaChatSubmit(new Event('submit'));
        }
      };

      // Handle errors
      _faseelaVoiceRecognition.onerror = function(event) {
        _faseelaVoiceActive = false;
        resetVoiceUI();

        let errorMsg = '';
        switch (event.error) {
          case 'not-allowed':
          case 'service-not-allowed':
            errorMsg = t('voice_error_no_mic');
            break;
          case 'no-speech':
            errorMsg = t('voice_error_no_speech');
            break;
          case 'network':
            errorMsg = isEn ? 'Network error. Check your connection.' : 'خطأ في الشبكة. تحقق من اتصالك بالإنترنت.';
            break;
          case 'aborted':
            // User cancelled — no toast needed
            return;
          default:
            errorMsg = t('voice_error_generic');
        }
        if (errorMsg) showToast(errorMsg);
      };

      // Start listening
      try {
        _faseelaVoiceRecognition.start();
      } catch (e) {
        _faseelaVoiceActive = false;
        resetVoiceUI();
        showToast(t('voice_error_generic'));
      }
    }

    function stopFaseelaVoiceInput() {
      if (_faseelaVoiceRecognition) {
        try {
          _faseelaVoiceRecognition.stop();
        } catch (e) {}
      }
      _faseelaVoiceActive = false;
      resetVoiceUI();
    }

    let _lastQuestionWasVoice = false;
    let _faseelaSpeakingBtn = null;

    function isSpeechSynthesisSupported() {
      return typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined';
    }

    function toggleFaseelaVoiceReplyMode() {
      if (!isSpeechSynthesisSupported()) {
        showToast(state.currentLang !== 'ar' ? 'Audio playback is not supported in this browser' : 'تشغيل الصوت غير مدعوم في هذا المتصفح');
        return;
      }
      state.faseelaVoiceReplyEnabled = !state.faseelaVoiceReplyEnabled;
      savePlatformState();
      updateVoiceReplyButtonUI();
      const isEn = state.currentLang !== 'ar';
      if (state.faseelaVoiceReplyEnabled) {
        showToast(isEn ? '🔊 Voice response enabled: Faseela will speak answers out loud.' : '🔊 تم تفعيل الرد الصوتي: ستتحدث فسيلة بصوتها للإجابة عن أسئلتك.');
      } else {
        if (window.speechSynthesis) window.speechSynthesis.cancel();
        showToast(isEn ? '🔇 Voice response turned off.' : '🔇 تم إيقاف الرد الصوتي التلقائي.');
      }
    }

    function updateVoiceReplyButtonUI() {
      const btn = document.getElementById('faseela-voice-reply-btn');
      const icon = document.getElementById('faseela-voice-reply-icon');
      if (!btn) return;
      if (state.faseelaVoiceReplyEnabled) {
        btn.classList.add('bg-emerald-500/20', 'text-emerald-300', 'ring-1', 'ring-emerald-400/40');
        btn.classList.remove('text-stone-300');
        if (icon) icon.setAttribute('data-lucide', 'volume-2');
      } else {
        btn.classList.remove('bg-emerald-500/20', 'text-emerald-300', 'ring-1', 'ring-emerald-400/40');
        btn.classList.add('text-stone-300');
        if (icon) icon.setAttribute('data-lucide', 'volume-x');
      }
      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        window.lucide.createIcons();
      }
    }

    function cleanHtmlForSpeech(html) {
      if (!html) return '';
      let text = html.replace(/<br\s*[\/]?>/gi, '. ')
                     .replace(/<\/li>/gi, '. ')
                     .replace(/<\/p>/gi, '. ')
                     .replace(/<\/div>/gi, '. ')
                     .replace(/<[^>]+>/g, ' ')
                     .replace(/&nbsp;/gi, ' ')
                     .replace(/&amp;/gi, '&')
                     .replace(/&quot;/gi, '"')
                     .replace(/&#39;/gi, "'")
                     .replace(/&lt;/gi, '<')
                     .replace(/&gt;/gi, '>')
                     .replace(/\s+/g, ' ')
                     .trim();
      return text;
    }

    function speakFaseelaResponse(btn) {
      if (!isSpeechSynthesisSupported()) {
        showToast(state.currentLang !== 'ar' ? 'Audio playback is not supported in this browser' : 'تشغيل الصوت غير مدعوم في هذا المتصفح');
        return;
      }

      // If already playing this button, stop it
      if (btn && btn.classList.contains('speaking-active')) {
        window.speechSynthesis.cancel();
        btn.classList.remove('speaking-active');
        const icon = btn.querySelector('[data-lucide]');
        if (icon) icon.setAttribute('data-lucide', 'volume-2');
        if (window.lucide) lucide.createIcons();
        _faseelaSpeakingBtn = null;
        return;
      }

      // Reset any previous speaking button
      if (_faseelaSpeakingBtn) {
        _faseelaSpeakingBtn.classList.remove('speaking-active');
        const prevIcon = _faseelaSpeakingBtn.querySelector('[data-lucide]');
        if (prevIcon) prevIcon.setAttribute('data-lucide', 'volume-2');
      }
      window.speechSynthesis.cancel();

      // Find the message text to speak
      let textToSpeak = '';
      if (btn) {
        const bubble = btn.closest('.chat-bubble-faseela');
        if (bubble) {
          const contentDiv = bubble.querySelector('.text-stone-700, .leading-relaxed');
          if (contentDiv) {
            textToSpeak = cleanHtmlForSpeech(contentDiv.innerHTML);
          }
        }
      }
      if (!textToSpeak) return;

      playFaseelaSpeechUtterance(textToSpeak, btn);
    }

    function playFaseelaSpeechUtterance(text, btn) {
      if (!isSpeechSynthesisSupported()) return;
      window.speechSynthesis.cancel();

      const utter = new SpeechSynthesisUtterance(text);
      utter.lang = state.currentLang !== 'ar' ? 'en-US' : 'ar-SY';
      utter.rate = 0.95;
      utter.pitch = 1.05;

      if (btn) {
        _faseelaSpeakingBtn = btn;
        btn.classList.add('speaking-active');
        const icon = btn.querySelector('[data-lucide]');
        if (icon) icon.setAttribute('data-lucide', 'volume-x');
        if (window.lucide) lucide.createIcons();

        utter.onend = () => {
          btn.classList.remove('speaking-active');
          if (icon) icon.setAttribute('data-lucide', 'volume-2');
          if (window.lucide) lucide.createIcons();
          _faseelaSpeakingBtn = null;
        };

        utter.onerror = () => {
          btn.classList.remove('speaking-active');
          if (icon) icon.setAttribute('data-lucide', 'volume-2');
          if (window.lucide) lucide.createIcons();
          _faseelaSpeakingBtn = null;
        };
      }

      try {
        window.speechSynthesis.speak(utter);
      } catch (e) {}
    }

    function resetVoiceUI() {
      const voiceBtn = document.getElementById('faseela-voice-btn');
      const statusBar = document.getElementById('faseela-voice-status');

      if (voiceBtn) {
        voiceBtn.classList.remove('voice-rec-active');
        // Remove pulsing ring
        const ring = document.getElementById('voice-rec-ring-el');
        if (ring) ring.remove();
        // Restore mic icon
        const icon = voiceBtn.querySelector('[data-lucide]');
        if (icon) {
          icon.setAttribute('data-lucide', 'mic');
          if (window.lucide) lucide.createIcons();
        }
      }
      if (statusBar) {
        statusBar.classList.add('hidden');
      }
    }

    function handleFaseelaChatSubmit(e) {
      e.preventDefault();
      const input = document.getElementById('faseela-chat-input');
      const question = input.value.trim();
      if (!question) return;

      const userKey = state.currentUser ? state.currentUser.id : 'guest';
      if (!rateLimiter.checkLimit('chat_' + userKey, 8, 20000)) {
        showToast(state.currentLang !== 'ar' ? '⚠️ Please slow down between questions.' : '⚠️ يرجى التمهل قليلاً بين الأسئلة لمنع الضغط وحماية سرعة الاستجابة.');
        return;
      }

      const container = document.getElementById('faseela-chat-messages');
      const now = new Date();
      const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      // Append user message
      container.insertAdjacentHTML('beforeend', `
        <div class="flex items-start gap-2.5 justify-end">
          <div class="p-3 max-w-[85%] text-white space-y-1 shadow-sm text-xs bg-gradient-to-r from-olive-800 to-olive-900 rounded-2xl rounded-tl-xs">
            <p class="leading-relaxed">${escapeHtml(question)}</p>
            <span class="text-[9px] text-olive-300 block text-start font-mono">${timeStr}</span>
          </div>
          <div class="w-7 h-7 rounded-full bg-stone-800 text-white flex-shrink-0 flex items-center justify-center text-[10px] font-black mt-0.5 shadow-xs">
            ${state.currentLang !== 'ar' ? 'You' : 'أنت'}
          </div>
        </div>
      `);
      faseelaChatHistory.push({ role: 'user', text: question, time: timeStr });
      saveChatHistory();

      input.value = '';
      container.scrollTop = container.scrollHeight;

      const typingId = `typing_${Date.now()}`;
      container.insertAdjacentHTML('beforeend', `
        <div id="${typingId}" class="flex items-start gap-2.5 justify-start">
          <div class="w-7 h-7 rounded-xl overflow-hidden flex-shrink-0 mt-0.5 shadow-sm border border-olive-600/30 animate-pulse">
            <img src="images/faseela-olive-tree-logo.svg" alt="فسيلة" class="w-full h-full object-cover">
          </div>
          <div class="chat-bubble-faseela p-3 text-stone-600 dark:text-stone-300 flex items-center gap-2 text-xs text-start">
            <span class="w-2 h-2 rounded-full bg-olive-600 animate-ping"></span>
            <span>${state.currentLang !== 'ar' ? 'Faseela is crafting your accurate answer...' : 'فسيلة تُحضر لك الإجابة الدقيقة...'}</span>
          </div>
        </div>
      `);
      lucide.createIcons();
      container.scrollTop = container.scrollHeight;

      setTimeout(() => {
        const typingEl = document.getElementById(typingId);
        if (typingEl) typingEl.remove();

        const answerHtml = generateFaseelaResponse(question);
        const replyTime = new Date();
        const replyTimeStr = `${replyTime.getHours().toString().padStart(2, '0')}:${replyTime.getMinutes().toString().padStart(2, '0')}`;

        container.insertAdjacentHTML('beforeend', `
          <div class="flex items-start gap-2.5 justify-start">
            <div class="w-7 h-7 rounded-xl overflow-hidden flex-shrink-0 mt-0.5 shadow-sm border border-olive-600/30">
              <img src="images/faseela-olive-tree-logo.svg" alt="فسيلة" class="w-full h-full object-cover">
            </div>
            <div class="chat-bubble-faseela p-3.5 max-w-[85%] text-stone-800 dark:text-stone-100 space-y-2.5 shadow-xs text-start">
              <div class="flex items-center justify-between border-b border-olive-200/50 dark:border-olive-800/50 pb-1">
                <span class="font-black text-olive-950 dark:text-olive-300 text-xs flex items-center gap-1">
                  <span>${state.currentLang !== 'ar' ? 'Faseela' : 'فسيلة'}</span>
                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 inline-block"></span>
                </span>
                <div class="flex items-center gap-1.5">
                  <button type="button" data-click="speakFaseelaResponse(this)" data-i18n-title="chat_listen_answer" title="${state.currentLang !== 'ar' ? 'Listen to answer' : 'استمع للإجابة'}" class="faseela-tts-btn text-stone-400 hover:text-olive-700 dark:hover:text-olive-300 p-0.5 rounded transition-all cursor-pointer">
                    <i data-lucide="volume-2" class="w-3.5 h-3.5"></i>
                  </button>
                  <span class="text-[9px] text-stone-400 font-mono">${replyTimeStr}</span>
                </div>
              </div>
              <div class="text-stone-700 dark:text-stone-200 space-y-2 leading-relaxed text-xs">
                ${answerHtml}
              </div>
            </div>
          </div>
        `);
        faseelaChatHistory.push({ role: 'assistant', html: answerHtml, time: replyTimeStr });
        saveChatHistory();

        lucide.createIcons();
        container.scrollTop = container.scrollHeight;

        // Auto-play voice response if voice reply mode is enabled or if question was voice-inputted
        if (state.faseelaVoiceReplyEnabled || _lastQuestionWasVoice) {
          _lastQuestionWasVoice = false;
          const lastBubbleBtn = container.querySelector('.chat-bubble-faseela:last-of-type .faseela-tts-btn');
          const cleanText = cleanHtmlForSpeech(answerHtml);
          playFaseelaSpeechUtterance(cleanText, lastBubbleBtn);
        }
      }, 500);
    }

