      const formattedBody = rawBody
        .replace(/{{INVESTOR_NAME}}/g, '<span class="text-purple-700 dark:text-purple-300 font-bold bg-purple-50 dark:bg-purple-950/60 px-1.5 py-0.5 rounded">طارق السوري (عينة فحص)</span>')
