    function insertVariableToContract(variableTag) {
      const textarea = document.getElementById('contract-edit-body-ar');
      if (!textarea) return;
      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const text = textarea.value;
      textarea.value = text.substring(0, start) + variableTag + text.substring(end);
      textarea.focus();
      textarea.selectionStart = textarea.selectionEnd = start + variableTag.length;
      syncContractLivePreview();
    }

    function saveActiveContractDraft() {
      const doc = founderContractsRegistry[activeEditingContractKey];
      if (!doc) return;

      doc.title_ar = document.getElementById('contract-edit-title-ar').value;
      doc.title_en = document.getElementById('contract-edit-title-en').value;
      doc.version = document.getElementById('contract-edit-version').value;
      doc.jurisdiction = document.getElementById('contract-edit-jurisdiction').value;
      doc.escrow_amount = document.getElementById('contract-edit-escrow-amount').value;
      doc.body_ar = document.getElementById('contract-edit-body-ar').value;

      try {
        localStorage.setItem('faseela_contracts_registry', JSON.stringify(founderContractsRegistry));
      } catch(e) {}

      playAcousticChime(750, 0.2);
      showToast(state.currentLang !== 'ar' ? '✓ Contract and deed clauses saved and activated across the platform!' : '✓ تم اعتماد وحفظ بنود الوثيقة وتطبيقها فورياً عبر كامل المنصة!');
      syncContractLivePreview();
    }

