    function openPlatformRestoreModal() {
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }

      const input = document.getElementById('fndr-restore-json-input');
      if (input) input.value = '';
      openModal('modal-fndr-restore-snapshot');
      if (window.lucide) window.lucide.createIcons();
    }

    function submitPlatformRestore(e) {
      if (e && e.preventDefault) e.preventDefault();
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }
      const input = document.getElementById('fndr-restore-json-input');
      if (!input || !input.value.trim()) return;

      try {
        const snapshot = JSON.parse(input.value.trim());
        const d = snapshot.data || snapshot;
        if (!d || !d.users || !Array.isArray(d.users)) {
          throw new Error('Invalid snapshot structure: missing users data array');
        }
        // SECURITY: Prototype pollution prevention
        const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
        function sanitizeObj(obj) {
          if (Array.isArray(obj)) return obj.map(sanitizeObj);
          if (obj && typeof obj === 'object') {
            dangerousKeys.forEach(k => delete obj[k]);
            Object.values(obj).forEach(v => { if (typeof v === 'object' && v !== null) sanitizeObj(v); });
          }
          return obj;
        }
        sanitizeObj(d);

        // Protect primary founder root clearance
        const founderInSeed = state.users.find(u => u.id === 'usr_founder_01');
        const restoredUsers = d.users.map(u => {
          if (u && typeof u === 'object') delete u.password;
          if (u.id === 'usr_founder_01' && founderInSeed) {
            return { ...u, email: 'founder@faseela.example', role: 'admin', verified: true, status: 'active' };
          }
          return u;
        });
        if (!restoredUsers.some(u => u.id === 'usr_founder_01') && founderInSeed) {
          restoredUsers.unshift(founderInSeed);
        }

        state.users = restoredUsers;
        if (d.trees && Array.isArray(d.trees)) state.trees = d.trees;
        if (d.virginGroves && Array.isArray(d.virginGroves)) state.virginGroves = d.virginGroves;
        if (d.userShares && Array.isArray(d.userShares)) state.userShares = d.userShares;
        if (d.millBatches && Array.isArray(d.millBatches)) state.millBatches = d.millBatches;
        if (d.transactions && Array.isArray(d.transactions)) state.transactions = d.transactions;
        if (d.farmerWallet) state.farmerWallet = d.farmerWallet;
        if (d.farmerPayouts) state.farmerPayouts = d.farmerPayouts;
        if (d.emergencyAlerts) state.emergencyAlerts = d.emergencyAlerts;
        if (d.escrowRate) state.escrowRate = d.escrowRate;
        if (d.notifications) state.notifications = d.notifications;

        savePlatformState();
        closeModal('modal-fndr-restore-snapshot');
        if (typeof renderFounderUsers === 'function') renderFounderUsers();
        if (typeof renderFounderFleet === 'function') renderFounderFleet();

        playAcousticChime(760, 0.25);
        showToast(state.currentLang !== 'ar' 
          ? 'Platform state snapshot restored and verified successfully' 
          : 'تمت استعادة اللقطة الاحتياطية للمنظومة والتحقق من صحتها بنجاح');
      } catch(err) {
        showToast(state.currentLang !== 'ar' ? `Failed to restore snapshot: ${err.message}` : `فشلت استعادة اللقطة: ${err.message}`);
      }
    }

