    // Enhanced Modal System: Backdrop Click & Escape Key Dismissal
    function setupModalInteractions() {
      if (window._modalInteractionsInitialized) return;
      window._modalInteractionsInitialized = true;

      document.querySelectorAll('[id^="modal-"]').forEach(modal => {
        modal.addEventListener('click', (e) => {
          if (e.target === modal) {
            closeModal(modal.id);
          }
        });
      });

      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          const visibleModals = Array.from(document.querySelectorAll('[id^="modal-"]')).filter(m => !m.classList.contains('hidden'));
          if (visibleModals.length > 0) {
            closeModal(visibleModals[visibleModals.length - 1].id);
          }
        }
      });
    }



