    function quickAdvanceVirginPhase(groveId) {
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }

      const vg = (state.virginGroves || []).find(g => g.id === groveId);
      if (!vg) return;

      const isEn = state.currentLang !== 'ar';
      const currentPhase = vg.development_phase || VIRGIN_GROVE_PHASES[0];
      const currentIndex = VIRGIN_GROVE_PHASES.indexOf(currentPhase);
      const nextIndex = (currentIndex + 1) % VIRGIN_GROVE_PHASES.length;
      const nextPhase = VIRGIN_GROVE_PHASES[nextIndex];

      vg.development_phase = nextPhase;
      vg.development_phase_en = nextPhase;

      savePlatformState();
      playAcousticChime(800, 0.25);
      showToast(isEn 
        ? `🚀 Project phase advanced to: "${nextPhase}"` 
        : `🚀 تم ترقية مرحلة المشروع الميدانية إلى: "${nextPhase}" بنجاح!`);

      renderFounderFleet('virgin');
      if (typeof renderVirginGroves === 'function') renderVirginGroves();
    }

