    // Virgin Grove Image Helpers
    function setVirginGroveActiveImage(imgUrl, mode) {
      if (!imgUrl) return;
      const previewEl = document.getElementById(`fndr-${mode}-vg-img-preview`);
      const urlInput = document.getElementById(`fndr-${mode}-vg-img-url`);
      if (previewEl) previewEl.src = imgUrl;
      if (urlInput) urlInput.value = imgUrl;
    }

    function updateVirginGroveImageFromUrl(val, mode) {
      const trimmed = (val || '').trim();
      if (!trimmed) return;
      const previewEl = document.getElementById(`fndr-${mode}-vg-img-preview`);
      if (previewEl) previewEl.src = trimmed;
    }

    function handleVirginGroveImageUpload(event, mode) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;

      if (!file.type.startsWith('image/')) {
        showToast(state.currentLang !== 'ar' ? '⚠️ Please select a valid image file (JPG, PNG, WebP).' : '⚠️ يرجى اختيار ملف صورة صالح (JPG, PNG, WebP).');
        return;
      }

      if (file.size > 5 * 1024 * 1024) {
        showToast(state.currentLang !== 'ar' ? '⚠️ Image file size exceeds 5MB limit.' : '⚠️ حجم الصورة يتجاوز الحد المسموح (5 ميغابايت).');
        return;
      }

      const reader = new FileReader();
      reader.onload = function(e) {
        const dataUrl = e.target.result;
        setVirginGroveActiveImage(dataUrl, mode);
        showToast(state.currentLang !== 'ar' ? '📸 Project image uploaded and preview updated!' : '📸 تم رفع صورة المشروع بنجاح وتحديث المعاينة اللحظية!');
        playAcousticChime(700, 0.2);
      };
      reader.readAsDataURL(file);
    }

    function clearVirginGroveImage(mode) {
      setVirginGroveActiveImage('images/tree_ancient_khodairi.webp', mode);
      const fileInput = document.getElementById(`fndr-${mode}-vg-file-input`);
      if (fileInput) fileInput.value = '';
    }

    function renderVirginGroveImagePresets(mode) {
      const container = document.getElementById(`fndr-${mode}-vg-presets`);
      if (!container) return;
      const isEn = state.currentLang !== 'ar';

      container.innerHTML = SYRIAN_TREE_IMAGE_PRESETS.map(preset => {
        const name = escapeHtml(isEn ? preset.name_en : preset.name_ar);
        return `
          <div data-path="${preset.path}" data-click="setVirginGroveActiveImage('${preset.path}', '${mode}')" class="group relative rounded-xl overflow-hidden cursor-pointer border border-stone-200 dark:border-stone-700 hover:border-emerald-500 transition-all shadow-2xs">
            <img loading="lazy" src="${preset.path}" alt="${name}" class="w-full h-12 object-cover group-hover:scale-110 transition-transform duration-300">
            <div class="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent flex items-end p-1">
              <span class="text-[9px] font-bold text-white truncate leading-tight">${name}</span>
            </div>
          </div>
        `;
      }).join('');
    }

