    // 4. Agricultural Commodity Pricing
    function saveAgriculturalPricing() {
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }

      const isEn = state.currentLang !== 'ar';
      if (!state.cropPricing) state.cropPricing = {};
      state.cropPricing.oil_liter = parseFloat(document.getElementById('fndr-price-oil')?.value) || 12.5;
      state.cropPricing.pistachio_kg = parseFloat(document.getElementById('fndr-price-pistachio')?.value) || 25.0;
      state.cropPricing.almond_kg = parseFloat(document.getElementById('fndr-price-almond')?.value) || 13.5;
      state.cropPricing.pomegranate_liter = parseFloat(document.getElementById('fndr-price-pomegranate')?.value) || 28.0;
      state.cropPricing.walnut_kg = parseFloat(document.getElementById('fndr-price-walnut')?.value) || 14.5;
      state.cropPricing.syp_usd_rate = parseFloat(document.getElementById('fndr-price-syp-rate')?.value) || 15000;

      savePlatformState();
      showToast(isEn ? "✅ Commodity prices and exchange rates saved globally." : "✅ تم حفظ أسعار المحاصيل وسعر الصرف وتطبيقها عبر كامل المنصة.");
      playAcousticChime(700, 0.2);
    }

    // 5. Disputes & Support Desk & Pricing Sync
    function renderFounderDisputesDesk() {
      // Sync commodity pricing and escrow inputs with state
      if (state.cropPricing) {
        const pOil = document.getElementById('fndr-price-oil');
        if (pOil && state.cropPricing.oil_liter !== undefined) pOil.value = state.cropPricing.oil_liter;
        const pPist = document.getElementById('fndr-price-pistachio');
        if (pPist && state.cropPricing.pistachio_kg !== undefined) pPist.value = state.cropPricing.pistachio_kg;
        const pAlm = document.getElementById('fndr-price-almond');
        if (pAlm && state.cropPricing.almond_kg !== undefined) pAlm.value = state.cropPricing.almond_kg;
        const pPom = document.getElementById('fndr-price-pomegranate');
        if (pPom && state.cropPricing.pomegranate_liter !== undefined) pPom.value = state.cropPricing.pomegranate_liter;
        const pWal = document.getElementById('fndr-price-walnut');
        if (pWal && state.cropPricing.walnut_kg !== undefined) pWal.value = state.cropPricing.walnut_kg;
        const pRate = document.getElementById('fndr-price-syp-rate');
        if (pRate && state.cropPricing.syp_usd_rate !== undefined) pRate.value = state.cropPricing.syp_usd_rate;
      }
      const escrowInput = document.getElementById('fndr-input-escrow-rate');
      if (escrowInput && state.escrowRate !== undefined) {
        escrowInput.value = state.escrowRate;
      }

      const list = document.getElementById('fndr-disputes-list');
      if (!list) return;
      const isEn = state.currentLang !== 'ar';

      const tickets = state.supportTickets || [];
      const pendingCount = tickets.filter(t => t.status === 'pending').length;
      const resolvedCount = tickets.filter(t => t.status === 'resolved').length;

      const cAll = document.getElementById('fndr-disputes-count-all');
      const cPending = document.getElementById('fndr-disputes-count-pending');
      const cResolved = document.getElementById('fndr-disputes-count-resolved');
      if (cAll) cAll.innerText = tickets.length;
      if (cPending) cPending.innerText = pendingCount;
      if (cResolved) cResolved.innerText = resolvedCount;

      let filtered = tickets;
      if (currentDisputeFilter && currentDisputeFilter !== 'all') {
        filtered = filtered.filter(t => t.status === currentDisputeFilter);
      }

      if (filtered.length === 0) {
        list.innerHTML = `
          <div class="p-6 text-center text-stone-400 font-bold bg-stone-50 dark:bg-stone-850 rounded-2xl border border-stone-200 dark:border-stone-700">
            ${isEn ? 'No disputes or support tickets matching filter' : 'لا توجد نزاعات أو تذاكر مطابقة للتصنيف المحدد'}
          </div>
        `;
        return;
      }

      list.innerHTML = filtered.map(tkt => {
        const isResolved = tkt.status === 'resolved';
        return `
          <div class="p-4 rounded-2xl border border-stone-200 dark:border-stone-700 bg-stone-50/80 dark:bg-stone-850 flex flex-col sm:flex-row sm:items-center justify-between gap-3 shadow-2xs hover:border-purple-300 dark:hover:border-purple-700 transition-all">
            <div class="space-y-1">
              <div class="flex items-center gap-2">
                <span class="font-mono font-bold text-[10px] text-purple-700 dark:text-purple-400">${escapeHtml(tkt.id)}</span>
                <h5 class="font-black text-stone-900 dark:text-white text-xs">${escapeHtml(tkt.subject)}</h5>
              </div>
              <p class="text-[11px] text-stone-500 dark:text-stone-400 flex items-center gap-1.5">
                <i data-lucide="user" class="w-3 h-3 text-stone-400"></i>
                <span>${escapeHtml(tkt.sender)}</span>
                <span>•</span>
                <i data-lucide="calendar" class="w-3 h-3 text-stone-400"></i>
                <span class="font-mono">${escapeHtml(tkt.date)}</span>
              </p>
              ${tkt.reply ? `
                <div class="bg-purple-50/80 dark:bg-purple-950/40 p-2.5 rounded-xl border border-purple-200 dark:border-purple-800/50 mt-2 text-[11px] text-purple-950 dark:text-purple-200">
                  <span class="font-bold flex items-center gap-1 mb-0.5 text-purple-800 dark:text-purple-300">
                    <i data-lucide="check-check" class="w-3.5 h-3.5"></i>
                    <span>${isEn ? 'Official Founder Resolution:' : 'قرار وتوجيه المؤسس التنفيذي:'}</span>
                  </span>
                  <p class="leading-relaxed font-medium">${escapeHtml(tkt.reply)}</p>
                </div>
              ` : ''}
            </div>
            <div class="flex items-center gap-2 self-end sm:self-center flex-shrink-0">
              <span class="text-[10px] font-black px-2.5 py-1 rounded-full ${isResolved ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300' : 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300'}">
                ${isResolved ? (isEn ? 'Resolved' : 'تم التحكيم والحل') : (isEn ? 'Pending Review' : 'بانتظار التحكيم')}
              </span>
              ${!isResolved ? `
                <button type="button" data-click="openSupportTicketReplyModal('${tkt.id}')" class="bg-purple-700 hover:bg-purple-800 text-white px-3 py-1.5 rounded-xl text-[11px] font-bold cursor-pointer transition-all shadow-xs flex items-center gap-1">
                  <i data-lucide="gavel" class="w-3.5 h-3.5 text-amber-300"></i>
                  <span>${isEn ? 'Arbitrate' : 'تحكيم وإصدار القرار'}</span>
                </button>
              ` : `
                <button type="button" data-click="openSupportTicketReplyModal('${tkt.id}')" class="bg-stone-200 dark:bg-stone-700 hover:bg-stone-300 text-stone-700 dark:text-stone-200 px-2.5 py-1.5 rounded-xl text-[10.5px] font-bold cursor-pointer transition-all">
                  ${isEn ? 'Edit Ruling' : 'تعديل التوجيه'}
                </button>
              `}
            </div>
          </div>
        `;
      }).join('');

      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        window.lucide.createIcons();
      }
    }

    function openSupportTicketReplyModal(tktId) {
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }

      const tkt = (state.supportTickets || []).find(t => t.id === tktId);
      if (!tkt) return;

      const idEl = document.getElementById('fndr-ticket-target-id');
      const senderEl = document.getElementById('fndr-ticket-sender-lbl');
      const dateEl = document.getElementById('fndr-ticket-date-lbl');
      const subjEl = document.getElementById('fndr-ticket-subject-lbl');
      const replyEl = document.getElementById('fndr-ticket-reply-text');

      if (idEl) idEl.value = tkt.id;
      if (senderEl) senderEl.innerText = `${state.currentLang !== 'ar' ? 'Sender:' : 'المُرسل:'} ${tkt.sender}`;
      if (dateEl) dateEl.innerText = tkt.date;
      if (subjEl) subjEl.innerText = tkt.subject;
      if (replyEl) replyEl.value = state.currentLang !== 'ar' 
        ? "Official Resolution: Reviewed and approved according to agricultural registry protocol." 
        : "توجيه إداري رسمي: تمت المراجعة والاعتماد وفق بروتوكول السجل الزراعي ومراجعة الدفعات.";

      openModal('modal-fndr-reply-ticket');
      playAcousticChime(600, 0.15);
    }

    function submitSupportTicketReply(e) {
      if (e && e.preventDefault) e.preventDefault();
      if (!state.currentUser || state.currentUser.role !== 'admin') {
        showToast(state.currentLang !== 'ar' ? 'Unauthorized: Founder root clearance required' : 'غير مصرح: يتطلب صلاحيات المدير العام');
        return;
      }
      const isEn = state.currentLang !== 'ar';
      const tktId = document.getElementById('fndr-ticket-target-id')?.value;
      const replyText = (document.getElementById('fndr-ticket-reply-text')?.value || '').trim();

      const tkt = (state.supportTickets || []).find(t => t.id === tktId);
      if (!tkt) return;

      tkt.status = 'resolved';
      tkt.reply = replyText;
      savePlatformState();

      closeModal('modal-fndr-reply-ticket');
      playAcousticChime(650, 0.2);
      showToast(isEn ? "✅ Ticket resolved and official reply dispatched." : "✅ تم اعتماد حل التذكرة وإرسال التوجيه الرسمي بنجاح.");
      renderFounderDisputesDesk();
    }

    function resolveSupportTicket(tktId) {
      openSupportTicketReplyModal(tktId);
    }

    // 6. Investor ESG & Statements
    function openEsgCertificateModal() {
      const isEn = state.currentLang !== 'ar';
      if (state.currentUser) {
        const nameEl = document.getElementById('esg-investor-name');
        if (nameEl) nameEl.innerText = (isEn ? (state.currentUser.name_en || state.currentUser.name) : state.currentUser.name) || (isEn ? "Eng. Wissam Al-Hamdoli" : "م. وسام الحمدولي");
      }
      openModal('modal-esg-certificate');
      playAcousticChime(650, 0.2);
    }

    function openInvestorTaxStatement() {
      openModal('modal-investor-statement');
      playAcousticChime(600, 0.2);
    }

    function openTrackOilDeliveryModal() {
      openModal('modal-track-oil-delivery');
      playAcousticChime(550, 0.2);
    }

    // 7. Mill Pomace & Tanks
    function submitPomaceDispatch() {
      const isEn = state.currentLang !== 'ar';
      const prodVal = document.getElementById('mill-pomace-product').value;
      const recipient = document.getElementById('mill-pomace-recipient').value.trim();
      const qty = parseFloat(document.getElementById('mill-pomace-qty').value) || 250;
      const driver = document.getElementById('mill-pomace-driver').value.trim() || 'جرار زراعي 4410';

      if (!recipient) {
        showToast(isEn ? "⚠️ Please enter recipient name" : "⚠️ يرجى إدخال اسم الجهة المستلمة");
        return;
      }

      state.pomaceDispatches.unshift({
        ref: `CIRC-2026-0${state.pomaceDispatches.length + 1}`,
        product_ar: prodVal === 'briquettes' ? 'حطب الجفت البيئي المضغوط' : 'سماد عضوي مخمر بلدي',
        product_en: prodVal === 'briquettes' ? 'Eco-Briquettes' : 'Organic Compost',
        recipient: recipient,
        qty_kg: qty,
        driver: driver,
        date: new Date().toISOString().split('T')[0],
        status: isEn ? 'Delivered' : 'تم التسليم'
      });

      closeModal('modal-log-pomace-dispatch');
      showToast(isEn ? `🌱 Logged dispatch of ${qty} kg to ${recipient}.` : `🌱 تم توثيق تسليم ${qty} كغ إلى ${recipient} بنجاح.`);
      playAcousticChime(700, 0.2);
      renderPomaceDispatchHistory();
    }

    function renderPomaceDispatchHistory() {
      const tbody = document.getElementById('mill-pomace-dispatch-tbody');
      if (!tbody || !state.pomaceDispatches) return;
      const isEn = state.currentLang !== 'ar';

      tbody.innerHTML = state.pomaceDispatches.map(item => `
        <tr class="hover:bg-stone-50 dark:hover:bg-stone-850/50 transition-all border-b border-stone-100 dark:border-stone-800 text-stone-800 dark:text-stone-200">
          <td class="py-2.5 px-3 font-mono font-bold">${item.ref}</td>
          <td class="py-2.5 px-3 font-bold">${isEn ? item.product_en : item.product_ar}</td>
          <td class="py-2.5 px-3 font-black">${item.recipient}</td>
          <td class="py-2.5 px-3 font-mono font-bold text-lime-700 dark:text-lime-400">${item.qty_kg} kg</td>
          <td class="py-2.5 px-3 text-[11px] text-stone-500">${item.driver}</td>
          <td class="py-2.5 px-3 font-mono text-[11px] text-stone-500">${item.date}</td>
          <td class="py-2.5 px-3 text-center">
            <span class="text-[10px] font-black px-2 py-0.5 rounded-full bg-lime-100 dark:bg-lime-950 text-lime-800 dark:text-lime-300">
              ${item.status}
            </span>
          </td>
        </tr>
      `).join('');
    }

    function openTankTransferModal() {
      const isEn = state.currentLang !== 'ar';
      const srcSel = document.getElementById('tank-source-select');
      const dstSel = document.getElementById('tank-target-select');
      const tanks = state.millTanks || [];

      if (srcSel && dstSel && tanks.length > 0) {
        srcSel.innerHTML = tanks.map((t, idx) => {
          const name = isEn ? t.name_en : t.name;
          return `<option value="${t.id}" ${idx === 0 ? 'selected' : ''}>${t.code} • ${name} (${t.current_liters}L متاح)</option>`;
        }).join('');

        dstSel.innerHTML = tanks.map((t, idx) => {
          const name = isEn ? t.name_en : t.name;
          return `<option value="${t.id}" ${idx === 1 ? 'selected' : ''}>${t.code} • ${name} (سعة ${t.capacity_liters}L)</option>`;
        }).join('');
      }

      openModal('modal-tank-transfer');
      playAcousticChime(550, 0.15);
      if (window.lucide && typeof window.lucide.createIcons === 'function') {
        lucide.createIcons();
      }
    }

    function submitTankTransfer() {
      const isEn = state.currentLang !== 'ar';
      const src = document.getElementById('tank-source-select').value;
      const dst = document.getElementById('tank-target-select').value;
      const liters = parseFloat(document.getElementById('tank-transfer-liters').value) || 100;

      if (src === dst) {
        showToast(isEn ? "⚠️ Source and destination tanks must be different." : "⚠️ يجب اختيار خزانين مختلفين لإتمام عملية المناقلة.");
        return;
      }

      const sTank = (state.millTanks || []).find(t => t.id === src);
      const dTank = (state.millTanks || []).find(t => t.id === dst);

      if (sTank && dTank) {
        if (sTank.current_liters < liters) {
          showToast(isEn ? `⚠️ Insufficient volume in ${sTank.name_en || sTank.name} (${sTank.current_liters}L available).` : `⚠️ الكمية المطلوبة تتجاوز المتاح في ${sTank.name} (${sTank.current_liters} لتر متاح).`);
          return;
        }
        if (dTank.current_liters + liters > dTank.capacity_liters) {
          showToast(isEn ? `⚠️ Target ${dTank.name_en || dTank.name} exceeds max capacity (${dTank.capacity_liters}L).` : `⚠️ الخزان الوجهة ${dTank.name} سيتجاوز سعته القصوى (${dTank.capacity_liters} لتر).`);
          return;
        }

        sTank.current_liters -= liters;
        dTank.current_liters += liters;
        savePlatformState();
        renderMillPortal();
      }

      closeModal('modal-tank-transfer');
      showToast(isEn ? `🔄 Successfully transferred ${liters}L EVOO from ${sTank ? (sTank.name_en || sTank.name) : src} to ${dTank ? (dTank.name_en || dTank.name) : dst}.` : `🔄 تمت مناقلة ${liters} لتر زيت بكر بنجاح بين الخزانات مع ضبط غاز النيتروجين الخامل.`);
      playAcousticChime(600, 0.2);
    }

    // 8. Farmer Mill Booking & Inputs
    function submitFarmerMillBooking() {
      const isEn = state.currentLang !== 'ar';
      const weight = parseInt(document.getElementById('farmer-book-weight').value, 10) || 750;
      const date = document.getElementById('farmer-book-date').value || "2026-09-18";
      const shift = document.getElementById('farmer-book-shift').value;
      const shiftStr = shift === 'morning' ? (isEn ? '08:00 AM (Morning)' : '08:00 صباحاً (وردية الصباح)') : (isEn ? '02:00 PM (Evening)' : '02:00 ظهراً (وردية المساء)');

      if (!state.millBatches) state.millBatches = [];
      const newBatch = {
        id: `mb_sched_${Date.now()}`,
        serial: `LOT-2026-DREIK-${Math.floor(100 + Math.random() * 900)}`,
        farmer_name: state.currentUser && state.currentUser.role === 'farmer' ? state.currentUser.name : "أبو جميل الكردي",
        farmer_name_en: state.currentUser && state.currentUser.role === 'farmer' ? (state.currentUser.name_en || state.currentUser.name) : "Abu Jamil Al-Kurdi",
        grove_name: "كروم الكردي - طرطوس",
        grove_name_en: "Al-Kurdi Groves - Tartous",
        weight_kg: weight,
        oil_extracted_liters: Math.round(weight * 0.216),
        acidity: "0.26%",
        status: "scheduled",
        status_ar: "موعد مؤكد بانتظار الاستلام",
        status_en: "Scheduled Slot Confirmed",
        temp_c: 23.4,
        date: date,
        shift: shift
      };
      state.millBatches.unshift(newBatch);
      savePlatformState();

      closeModal('modal-farmer-book-mill');
      showToast(isEn ? `📅 Cold-press milling reserved for ${weight} kg on ${date} (${shiftStr}).` : `📅 تم تأكيد حجز دور العصر البارد لـ ${weight} كغ بتاريخ ${date} (${shiftStr}) بنجاح مع معصرة الدريكيش.`);
      playAcousticChime(750, 0.2);

      const slotEl = document.querySelector('[data-i18n="farmer_mill_slot_time"]');
      if (slotEl) slotEl.innerText = `${date} • ${shiftStr}`;

      renderFarmerPortal();
      if (state.currentPage === 'mill-portal') renderMillPortal();
    }

    function submitFarmerInputsRequest() {
      const isEn = state.currentLang !== 'ar';
      const item = document.getElementById('farmer-req-item-select').value;
      const qty = parseInt(document.getElementById('farmer-req-qty').value, 10) || 20;
      const date = document.getElementById('farmer-req-date').value || new Date().toISOString().split('T')[0];

      const itemLabels = {
        crates_50: { ar: 'صناديق قطاف مهواة', en: 'Ventilated Harvest Crates' },
        nets_4: { ar: 'شباك قطاف إيطالية ناعمة', en: 'Italian Soft Harvest Nets' },
        pruning_kit: { ar: 'طقم مقصات ومنشار تقليم هوائي', en: 'Pneumatic Pruning Shears & Saw Kit' },
        compost_bag: { ar: 'أكياس سماد عضوي مخمر ومعالج حرارياً', en: 'Organic Fermented Compost Bags' }
      };

      const meta = itemLabels[item] || { ar: 'مستلزمات زراعية', en: 'Agricultural Equipment' };

      if (!state.farmerRequisitions) state.farmerRequisitions = [];
      state.farmerRequisitions.unshift({
        id: `req_${Date.now()}`,
        item: `${meta.ar} (${qty} قطعة)`,
        item_en: `${meta.en} (${qty} pcs)`,
        date: date,
        status: "قيد التجهيز والشحن للمزرعة",
        status_en: "Preparing for Field Dispatch",
        status_color: "amber"
      });

      savePlatformState();
      closeModal('modal-farmer-request-inputs');
      showToast(isEn ? `📦 Requisition confirmed: ${qty} units of ${meta.en} scheduled for delivery on ${date}.` : `📦 تم تأكيد طلب ${qty} من ${meta.ar} بنجاح: التسليم مجدول بتاريخ ${date}.`);
      playAcousticChime(650, 0.2);
      renderFarmerPortal();
    }

    function openFarmerAddTaskModal() {
      openModal('modal-farmer-add-task');
    }

    function submitFarmerCustomTask() {
      const isEn = state.currentLang !== 'ar';
      const title = document.getElementById('farmer-task-title-input').value.trim();
      const wage = parseInt(document.getElementById('farmer-task-wage-input').value, 10) || 350000;

      if (!title) {
        showToast(isEn ? "⚠️ Please enter task title" : "⚠️ يرجى إدخال عنوان المهمة");
        return;
      }

      if (state.farmerTasks) {
        state.farmerTasks.unshift({
          id: `task_custom_${Date.now()}`,
          title: title,
          title_en: title,
          tree_name: "بساتين كروم الكردي",
          tree_name_en: "Al-Kurdi Groves",
          wage_syp: wage,
          status: "pending",
          date: new Date().toISOString().split('T')[0]
        });
      }

      closeModal('modal-farmer-add-task');
      showToast(isEn ? `✅ Custom agricultural task logged with wage credit of ${wage.toLocaleString()} SYP.` : `✅ تم قيد المهمة الميدانية برصيد ${wage.toLocaleString()} ل.س بنجاح.`);
      playAcousticChime(800, 0.2);

      if (typeof renderFarmerPortal === 'function') renderFarmerPortal();
    }

    // Unified switchFounderSubTab
    window.switchFounderSubTab = switchFounderSubTab;

    // Override logPomaceDispatch to open modal
    window.logPomaceDispatch = function() {
      const isEn = state.currentLang !== 'ar';
      if (!state.currentUser || (state.currentUser.role !== 'mill_owner' && state.currentUser.role !== 'admin')) {
        const reqRole = isEn ? 'Certified Mill Operator' : 'صاحب معصرة معتمد';
        const msg = isEn ? 'Logging circular economy distribution is restricted to mill operators.' : 'تسجيل دفعات توزيع الجفت والسماد مقتصر على أصحاب المعاصر المعتمدين.';
        showAccessDenied(t('mill_circ_title'), reqRole, msg);
        return;
      }
      openModal('modal-log-pomace-dispatch');
    };

    // Override bookFarmerMillDelivery to open modal
    window.bookFarmerMillDelivery = function() {
      const isEn = state.currentLang !== 'ar';
      if (!state.currentUser || (state.currentUser.role !== 'farmer' && state.currentUser.role !== 'admin')) {
        const reqRole = isEn ? 'Certified Field Farmer' : 'مزارع ميداني معتمد';
        const msg = isEn ? 'Mill slot booking is restricted to certified farmers.' : 'حجز دور المعصرة مقتصر على المزارعين المعتمدين.';
        showAccessDenied(t('farmer_mill_booking_title'), reqRole, msg);
        return;
      }
      openModal('modal-farmer-book-mill');
    };

    // Override requestFarmerInput to open modal
    window.requestFarmerInput = function() {
      openModal('modal-farmer-request-inputs');
    };

